// No network calls here - parses the FMP gainers response.
// FMP's stable/biggest-gainers endpoint returns a flat JSON array, which the
// HTTP Request node splits into one item per element.
const rows = $input.all().map(i => i.json).filter(x => x && x.symbol);
rows.sort((a, b) => (b.changesPercentage || 0) - (a.changesPercentage || 0));
const symbols = [...new Set(rows.map(x => x.symbol))].slice(0, 25);
return symbols.map(symbol => ({ json: { symbol } }));

// No network calls here - filtering only.
const MIN_GAP     = 5;
const PRICE_MIN   = 2;
const PRICE_MAX   = 20;
const MAX_RESULTS = 10;

const items = $input.all();
const rows = [];
items.forEach((item, idx) => {
  let symbol;
  try {
    symbol = $('Extract Candidates').itemMatching(idx).json.symbol;
  } catch (e) {
    return;
  }
  const q = item.json;
  if (!symbol || !q || !q.c || !q.pc) return;
  const gap = ((q.c - q.pc) / q.pc) * 100;
  if (gap >= MIN_GAP && q.c >= PRICE_MIN && q.c <= PRICE_MAX) {
    rows.push({ symbol, price: q.c, prevClose: q.pc, gap, dayHigh: q.h || 0 });
  }
});
rows.sort((a, b) => b.gap - a.gap);
const top = rows.slice(0, MAX_RESULTS);
return top.map(r => ({ json: r }));

// No network calls here - formatting only.
const newsItems = $input.all();
const firstHeadlineByIndex = {};
for (const item of newsItems) {
  const pi = item.pairedItem;
  const idx = Array.isArray(pi) ? pi[0].item : (pi ? pi.item : undefined);
  if (idx === undefined || idx in firstHeadlineByIndex) continue;
  const body = item.json;
  const headline = Array.isArray(body) ? (body[0] && body[0].headline) : (body && body.headline);
  firstHeadlineByIndex[idx] = headline || null;
}

const top = $('Filter Gappers').all()
  .map((item, idx) => ({ ...item.json, catalyst: firstHeadlineByIndex[idx] || '— no fresh headline —' }))
  .filter(r => r.symbol);

const dateLabel = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
let html = `<h2 style="font-family:monospace">Final premarket brief — ${dateLabel}</h2>`;
html += `<table cellpadding="8" style="border-collapse:collapse;font-family:monospace">
  <tr style="text-align:left;border-bottom:1px solid #444">
    <th>Ticker</th><th>Gap</th><th>Price</th><th>High</th><th>Catalyst</th></tr>`;
for (const r of top) {
  html += `<tr style="border-bottom:1px solid #222">
    <td><b>${r.symbol}</b></td>
    <td style="color:#16c784">+${r.gap.toFixed(1)}%</td>
    <td>$${r.price.toFixed(2)}</td>
    <td>$${(r.dayHigh||0).toFixed(2)}</td>
    <td>${r.catalyst}</td></tr>`;
}
html += `</table>`;
html += `<p style="font-family:monospace;color:#888;margin-top:16px">Rules: catalyst required · check float on the scanner · mental stop before entry · 1% risk · focus window 14:30–16:30 BST.</p>`;
return [{ json: { subject: `Final premarket brief — ${dateLabel}`, html } }];

